// C18-C21 (analysis side), M8 (classification exactness), M9 (dnd5e 3.x documents recovered).
// Skeleton: not yet run in a real Foundry. Truth comes from tests/fixtures/conformity-expected.json
// and legacy-3x-expected.json (generated by tests/fixtures/generate.mjs).
import { expect, test } from "../../../../test-env/fixtures.mjs";
import {
  clientDeletePacks, clientPipeline, clientReadPack, clientSnapshot, fixtureJson, fixtureText, uniqueName
} from "./helpers.mjs";

const created = [];
test.afterEach(async ({ foundry }) => {
  if (created.length) await foundry(clientDeletePacks, created.splice(0));
});

function newPack(prefix, type) {
  const name = uniqueName(prefix);
  created.push(name);
  return { name, spec: { label: `${prefix} ${name}`, name, type } };
}

const expected = fixtureJson("conformity-expected.json");
const truthFor = (documentName) => expected.documents.filter((d) => d.documentName === documentName);

for (const [documentName, file] of [["Item", "conformity-items.json"], ["Actor", "conformity-actors.json"]]) {
  test(`M8/C18: analysis of ${file} classifies every ${documentName} like the truth file`, async ({ foundry }) => {
    const before = await foundry(clientSnapshot);
    const result = await foundry(clientPipeline, { text: fixtureText(file), fileName: file, documentName, dryRun: true });
    const truth = truthFor(documentName);
    const accepted = new Set(result.accepted.map((d) => d.name));
    const rejected = new Set(result.rejected.map((d) => d.name));

    const wronglyImported = truth.filter((t) => !t.conform && accepted.has(t.name)).map((t) => `${t.name} (${t.defect})`);
    const wronglyRejected = truth.filter((t) => t.conform && rejected.has(t.name)).map((t) => `${t.name}: ${result.rejected.find((r) => r.name === t.name)?.reasons.join(" | ")}`);
    const unclassified = truth.filter((t) => !accepted.has(t.name) && !rejected.has(t.name)).map((t) => t.name);

    test.info().annotations.push({
      type: `M8-${documentName}`,
      description: `${truth.length - wronglyImported.length - wronglyRejected.length - unclassified.length}/${truth.length} well classified`
    });
    expect(wronglyImported, "non conforming documents that would be imported").toEqual([]);
    expect(wronglyRejected, "conforming documents that would be rejected").toEqual([]);
    expect(unclassified).toEqual([]);
    expect(await foundry(clientSnapshot), "analysis must not write").toEqual(before);
  });

  test(`C20: importing ${file} writes the conforming documents only`, async ({ foundry }) => {
    const pack = newPack("conf", documentName);
    const result = await foundry(clientPipeline, { text: fixtureText(file), fileName: file, documentName, newPack: pack.spec });
    const truth = truthFor(documentName);
    const stored = (await foundry(clientReadPack, `world.${pack.name}`)).map((d) => d.name).sort();
    expect(stored).toEqual(truth.filter((t) => t.conform).map((t) => t.name).sort());
    expect(result.created).toBe(truth.filter((t) => t.conform).length);
    for (const t of truth.filter((x) => !x.conform)) expect(stored).not.toContain(t.name);
  });

  test(`C20: every rejected ${documentName} has a name, a type and readable reasons`, async ({ foundry }) => {
    const result = await foundry(clientPipeline, { text: fixtureText(file), fileName: file, documentName, dryRun: true });
    expect(result.rejected.length).toBeGreaterThan(0);
    for (const r of result.rejected) {
      expect(r.name, "name").toBeTruthy();
      expect(r.type, `type of ${r.name}`).toBeTruthy();
      expect(r.reasons.length, `reasons of ${r.name}`).toBeGreaterThan(0);
      for (const reason of r.reasons) {
        // A raw i18n key (not translated) looks like "compendium-json-importer.reason.xxx" or "reason.xxx {...}".
        expect(reason, `reason of ${r.name}`).not.toMatch(/^(compendium-json-importer\.)?reason\./);
        expect(reason.trim().length).toBeGreaterThan(5);
      }
    }
  });
}

test("C18: a legacy 'backpack' item is accepted as a container", async ({ foundry }) => {
  const doc = fixtureJson("conformity-items.json").find((d) => d.name === "Ok Legacy Backpack Alias");
  const result = await foundry(clientPipeline, { text: JSON.stringify([doc]), fileName: "b.json", documentName: "Item", dryRun: true });
  expect(result.rejected).toEqual([]);
  expect(result.accepted).toHaveLength(1);
});

test("C21: documents of other types are counted apart and not checked", async ({ foundry }) => {
  const text = fixtureText("formats/mixed-types.json");
  const result = await foundry(clientPipeline, { text, fileName: "mixed.json", documentName: "JournalEntry", dryRun: true });
  expect(result.accepted).toEqual([]);
  expect(result.rejected).toEqual([]);
  expect(result.other).toBe(4);
});

// ------------------------------------------------------------------ M9

const legacyDocs = fixtureJson("legacy-3x.json");
const legacyTruth = fixtureJson("legacy-3x-expected.json");
const isActor = (d) => ["npc", "character"].includes(d.type);

test("M9/C19: every dnd5e 3.x document is accepted, counted as updated and gets its activities", async ({ foundry }) => {
  const results = [];
  for (const [documentName, docs] of [["Item", legacyDocs.filter((d) => !isActor(d))], ["Actor", legacyDocs.filter(isActor)]]) {
    const pack = newPack("legacy", documentName);
    const result = await foundry(clientPipeline, { text: JSON.stringify(docs), fileName: "legacy.json", documentName, newPack: pack.spec });
    const stored = await foundry(async (id) => {
      const out = [];
      for (const doc of await game.packs.get(id).getDocuments()) {
        out.push({
          name: doc.name,
          activities: doc.system.activities?.size ?? null,
          nested: Object.fromEntries((doc.items ?? []).map((i) => [i.name, i.system.activities?.size ?? 0]))
        });
      }
      return out;
    }, `world.${pack.name}`);
    results.push({ documentName, docs, result, stored });
  }

  const failures = [];
  let good = 0;
  for (const { docs, result, stored } of results) {
    expect(result.rejected, JSON.stringify(result.rejected.map((r) => [r.name, r.reasons]))).toEqual([]);
    for (const doc of docs) {
      const truth = legacyTruth.find((t) => t.name === doc.name);
      const accepted = result.accepted.find((a) => a.name === doc.name);
      const item = stored.find((s) => s.name === doc.name);
      const problems = [];
      if (!accepted) problems.push("not accepted");
      else if (!accepted.updated) problems.push("not counted as updated");
      if (!item) problems.push("not stored");
      else {
        if (truth.expectActivities && !(item.activities >= 1)) problems.push("no activity");
        for (const nested of truth.nestedWithActivities) if (!(item.nested[nested] >= 1)) problems.push(`nested ${nested} has no activity`);
      }
      if (problems.length) failures.push(`${doc.name}: ${problems.join(", ")}`);
      else good++;
    }
  }
  test.info().annotations.push({ type: "M9", description: `${good}/${legacyDocs.length} recovered` });
  expect(failures).toEqual([]);
  expect(good).toBe(legacyDocs.length);
});

test("C19: the summary count of updated documents matches (the 3.x set is entirely 'updated')", async ({ foundry }) => {
  const docs = legacyDocs.filter((d) => !isActor(d));
  const result = await foundry(clientPipeline, { text: JSON.stringify(docs), fileName: "legacy.json", documentName: "Item", dryRun: true });
  expect(result.accepted.filter((a) => a.updated)).toHaveLength(docs.length);
});

test("C19: an up-to-date document is not counted as updated", async ({ foundry }) => {
  const doc = fixtureJson("conformity-items.json").find((d) => d.name === "Ok Longsword Active");
  const result = await foundry(clientPipeline, { text: JSON.stringify([doc]), fileName: "u.json", documentName: "Item", dryRun: true });
  expect(result.accepted).toHaveLength(1);
  expect(result.accepted[0].updated).toBe(false);
});
